/*
 * kmem.c - Windows kernel driver: user buffer mapping + virtual address range read/write
 *
 * TODO: Implement full IRP dispatch, symbolic link, and device cleanup.
 *
 * Build: WDK, compile as kernel-mode driver (C).
 */

#include <ntddk.h>
#include <wdm.h>

/* -----------------------------------------------------------------------
 * IOCTL codes
 * ----------------------------------------------------------------------- */
#define KMEM_DEVICE_TYPE    0x8000
#define IOCTL_KMEM_READ     CTL_CODE(KMEM_DEVICE_TYPE, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE    CTL_CODE(KMEM_DEVICE_TYPE, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* -----------------------------------------------------------------------
 * Request structures (shared with user-mode caller)
 * ----------------------------------------------------------------------- */
#pragma pack(push, 1)
typedef struct _KMEM_REQUEST {
    ULONG_PTR TargetVa;   /* virtual address in the target process */
    SIZE_T    Length;     /* bytes to transfer                     */
    /* For READ:  output follows immediately in the output buffer.
       For WRITE: data to write follows immediately in the input buffer
                  after this header.                                     */
} KMEM_REQUEST, *PKMEM_REQUEST;
#pragma pack(pop)

/* -----------------------------------------------------------------------
 * Forward declarations
 * ----------------------------------------------------------------------- */
DRIVER_UNLOAD       KmemUnload;
DRIVER_DISPATCH     KmemCreate;
DRIVER_DISPATCH     KmemClose;
DRIVER_DISPATCH     KmemDeviceControl;

static UNICODE_STRING g_DeviceName  = RTL_CONSTANT_STRING(L"\\Device\\KmemDrv");
static UNICODE_STRING g_SymlinkName = RTL_CONSTANT_STRING(L"\\DosDevices\\KmemDrv");

/* -----------------------------------------------------------------------
 * DriverEntry
 * ----------------------------------------------------------------------- */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath)
{
    NTSTATUS       status;
    PDEVICE_OBJECT deviceObject = NULL;

    UNREFERENCED_PARAMETER(RegistryPath);

    /* Create the device object. */
    status = IoCreateDevice(
        DriverObject,
        0,
        &g_DeviceName,
        FILE_DEVICE_UNKNOWN,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,
        &deviceObject);

    if (!NT_SUCCESS(status)) {
        return status;
    }

    /* Expose a user-mode accessible symbolic link. */
    status = IoCreateSymbolicLink(&g_SymlinkName, &g_DeviceName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(deviceObject);
        return status;
    }

    /* Wire up dispatch routines. */
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KmemCreate;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KmemClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KmemDeviceControl;
    DriverObject->DriverUnload                         = KmemUnload;

    /* METHOD_BUFFERED: the I/O manager handles the copy in/out. */
    deviceObject->Flags |= DO_BUFFERED_IO;
    deviceObject->Flags &= ~DO_DEVICE_INITIALIZING;

    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemUnload
 * ----------------------------------------------------------------------- */
VOID
KmemUnload(_In_ PDRIVER_OBJECT DriverObject)
{
    IoDeleteSymbolicLink(&g_SymlinkName);
    if (DriverObject->DeviceObject) {
        IoDeleteDevice(DriverObject->DeviceObject);
    }
}

/* -----------------------------------------------------------------------
 * KmemCreate / KmemClose  (pass-through)
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemCreate(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

NTSTATUS
KmemClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    UNREFERENCED_PARAMETER(DeviceObject);
    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemMapAndTransfer
 *
 * Maps [TargetVa, TargetVa+Length) from the calling process into a kernel
 * MDL and either copies to or from KernelBuffer.
 *
 * isWrite == FALSE  =>  read from user VA  into KernelBuffer
 * isWrite == TRUE   =>  write from KernelBuffer into user VA
 * ----------------------------------------------------------------------- */
static NTSTATUS
KmemMapAndTransfer(
    _In_    ULONG_PTR  TargetVa,
    _In_    SIZE_T     Length,
    _Inout_ PVOID      KernelBuffer,
    _In_    BOOLEAN    isWrite)
{
    NTSTATUS  status  = STATUS_SUCCESS;
    PMDL      mdl     = NULL;
    PVOID     mapped  = NULL;

    /* Sanity-check: refuse zero-length or obviously bogus requests. */
    if (Length == 0 || Length > 64 * 1024 * 1024ULL) {
        return STATUS_INVALID_PARAMETER;
    }

    /* Allocate an MDL describing the user-mode buffer.
     * IoAllocateMdl does NOT lock pages; we do that next. */
    mdl = IoAllocateMdl((PVOID)(ULONG_PTR)TargetVa, (ULONG)Length,
                        FALSE, FALSE, NULL);
    if (!mdl) {
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    /* Lock the pages into physical memory.
     * We run at PASSIVE_LEVEL (IOCTL path) so this is legal. */
    __try {
        MmProbeAndLockPages(mdl,
                            UserMode,
                            isWrite ? IoWriteAccess : IoReadAccess);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(mdl);
        return STATUS_ACCESS_VIOLATION;
    }

    /* Map the locked pages into kernel virtual address space. */
    mapped = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority |
                                               MdlMappingNoExecute);
    if (!mapped) {
        MmUnlockPages(mdl);
        IoFreeMdl(mdl);
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    /* Perform the transfer. */
    __try {
        if (!isWrite) {
            /* READ: user VA -> kernel buffer */
            RtlCopyMemory(KernelBuffer, mapped, Length);
        } else {
            /* WRITE: kernel buffer -> user VA */
            RtlCopyMemory(mapped, KernelBuffer, Length);
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = STATUS_ACCESS_VIOLATION;
    }

    /* Clean up: unmap, unlock, free the MDL. */
    MmUnmapLockedPages(mapped, mdl);
    MmUnlockPages(mdl);
    IoFreeMdl(mdl);

    return status;
}

/* -----------------------------------------------------------------------
 * KmemDeviceControl  –  IOCTL dispatcher
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp)
{
    NTSTATUS            status;
    PIO_STACK_LOCATION  stack;
    ULONG               controlCode;
    PVOID               sysBuffer;      /* METHOD_BUFFERED shared buffer     */
    ULONG               inputLength;
    ULONG               outputLength;
    PKMEM_REQUEST       req;
    PVOID               dataBuf = NULL;
    ULONG               dataLen;

    UNREFERENCED_PARAMETER(DeviceObject);

    stack         = IoGetCurrentIrpStackLocation(Irp);
    controlCode   = stack->Parameters.DeviceIoControl.IoControlCode;
    sysBuffer     = Irp->AssociatedIrp.SystemBuffer;
    inputLength   = stack->Parameters.DeviceIoControl.InputBufferLength;
    outputLength  = stack->Parameters.DeviceIoControl.OutputBufferLength;

    Irp->IoStatus.Information = 0;

    switch (controlCode) {

    /* ------------------------------------------------------------------
     * IOCTL_KMEM_READ
     *
     * Input  (inputLength):  KMEM_REQUEST
     * Output (outputLength): raw bytes read from TargetVa
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_READ:
    {
        if (inputLength < sizeof(KMEM_REQUEST) || !sysBuffer) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        req     = (PKMEM_REQUEST)sysBuffer;
        dataLen = (ULONG)req->Length;

        if (dataLen == 0 || dataLen > outputLength) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        /* The output goes straight into the buffered-I/O system buffer. */
        status = KmemMapAndTransfer(req->TargetVa, dataLen,
                                    sysBuffer,  /* reuse for output */
                                    FALSE);

        /*
         * NOTE: for a clean protocol the caller should use a separate
         * output buffer.  Here we write the read data starting at byte 0
         * of sysBuffer (overlapping the request header) which is fine
         * because the header is consumed before the transfer.
         */
        if (NT_SUCCESS(status)) {
            Irp->IoStatus.Information = dataLen;
        }
        break;
    }

    /* ------------------------------------------------------------------
     * IOCTL_KMEM_WRITE
     *
     * Input  (inputLength):  KMEM_REQUEST + data to write
     * Output: none
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_WRITE:
    {
        if (inputLength <= sizeof(KMEM_REQUEST) || !sysBuffer) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        req     = (PKMEM_REQUEST)sysBuffer;
        dataLen = (ULONG)req->Length;

        /* Data immediately follows the header in the input buffer. */
        if (dataLen == 0 ||
            (ULONG)(sizeof(KMEM_REQUEST) + dataLen) > inputLength) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        dataBuf = (PUCHAR)sysBuffer + sizeof(KMEM_REQUEST);

        status = KmemMapAndTransfer(req->TargetVa, dataLen,
                                    dataBuf,
                                    TRUE);

        if (NT_SUCCESS(status)) {
            Irp->IoStatus.Information = 0;
        }
        break;
    }

    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

    Irp->IoStatus.Status = status;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}
